              <g
                key={`${period.id}-${item.label}`}
                transform={`rotate(${stacked ? -180 : -90} 130 115.5)`}
                onMouseEnter={() => setActive(i)}
                onMouseLeave={() => setActive(null)}
                opacity={active != null && active !== i ? 0.25 : 1}
                className="transition-opacity duration-200 motion-reduce:transition-none"
              >
                {variant !== "grid" && !stacked && (
                  <circle
                    cx={130}
                    cy={115.5}
                    r={r}
                    fill="none"
                    stroke="var(--color-chart-track)"
                    strokeWidth={width}
                  />
                )}
                <motion.circle
                  key={reduced ? "reduced" : "animated"}
                  id={`${id}-${i}`}
                  cx={130}
                  cy={115.5}
                  r={r}
                  pathLength={100}
                  fill="none"
                  stroke={color}
                  strokeWidth={width}
                  strokeLinecap="round"
                  strokeDashoffset={stacked ? -start : 0}
                  initial={reduced ? false : { strokeDasharray: "0 100" }}
                  animate={{ strokeDasharray: `${Math.max(0, progress - (stacked ? 1 : 0))} 100` }}
                  transition={{ duration: reduced ? 0 : 0.7, ease: "easeOut" }}
                />
                {variant === "labels" && (
                  <text fill="var(--color-text-primary)" fontSize={10} dy={3}>
                    <textPath href={`#${id}-${i}`} startOffset="3%">
                      {item.label}
                    </textPath>
                  </text>
                )}
              </g>
            );
          })}
        </svg>
        {(single || stacked) && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-title-1-medium text-text-primary">
              <AnimatedNumber value={percent} />%
            </span>
            <span className="text-body-2-regular text-text-secondary">
              {stacked ? primary?.label : "of goal"}
            </span>
          </div>
        )}
      </div>
    </ChartFrame>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};
const clientSnapshot = () => true;
const serverSnapshot = () => false;

/** Keep the first server/client render identical, then apply the user's motion preference. */
export function useHydratedReducedMotion(): boolean {
  const reduced = useReducedMotion();
  const hydrated = useSyncExternalStore(subscribe, clientSnapshot, serverSnapshot);
  return hydrated && reduced === true;
}
